import { expect, test } from "../../fixtures";

test.describe("manage vendors", () => {
  test("pagination limit above 100 is rejected", { tag: "@VEN-06" }, async ({ apiAs }) => {
    // Arrange: signed in as a member (Background)
    const member = await apiAs("member");

    // Act: list vendors with limit 101
    const res = await member.get("/api/vendors?limit=101");

    // Assert: response status is 422
    expect(res.status(), await res.text()).toBe(422);
  });
});
